steps.script:
for c in tree.root.get_children():
	if c is Window and c != tree.root and str(c.name) == "DisembarkDialog":
		c.hide()
		c.queue_free()
return true

var u = GameState.get_unit("U_MORKANAUT_A")
var ok := true
for m in u.models:
	if not m.get("alive", true) or m.get("position", null) == null:
		continue
	var p = m.position
	var r = NetworkIntegration.route_action({"type": "STAGE_MODEL_MOVE", "player": 1, "actor_unit_id": "U_MORKANAUT_A", "payload": {"model_id": str(m.id), "dest": [float(p.x) + 0.0, float(p.y) + 40.0], "rotation": float(m.get("rotation", 0.0))}})
	if not r.get("success", false):
		print("[wp-o6] stage failed ", m.id, " ", r.get("error", r.get("errors", "")))
		ok = false
tree.current_scene._recreate_unit_visuals()
return ok
